CREATE TABLE `deliveries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `time_slot` time NOT NULL,
  `duration_min` int NOT NULL DEFAULT '15',
  `unload_place` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_id` int DEFAULT NULL,
  `material_id` int DEFAULT NULL,
  `quantity` int NOT NULL,
  `status` enum('planned','in_transit','delivered','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'planned',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `actual_date` date DEFAULT NULL,
  `actual_time` time DEFAULT NULL,
  `quality_score` int DEFAULT NULL,
  `result_notes` text COLLATE utf8mb4_unicode_ci,
  `delay_minutes` int DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_deliveries_date` (`date`),
  KEY `idx_deliveries_date_time` (`date`,`time_slot`),
  KEY `fk_deliveries_supplier` (`supplier_id`),
  KEY `fk_deliveries_material` (`material_id`),
  KEY `fk_deliveries_created_by` (`created_by`),
  CONSTRAINT `fk_deliveries_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_deliveries_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_deliveries_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=403 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
