INSERT INTO `potential_suppliers` VALUES (1,'Girteka Logistics',NULL,NULL,NULL,NULL,'Краска',5000.00,10,3.40,5,0.600,0.500,0.300,6.49,'not_recommended','Работал там ради английской визы на 2 года. Опыт хороший для старта и самый дешёвый код 95 с бесплатным проживанием, обучение классное, педагоги топ. Для каденций фирма хороша, а вот как мне живущего в Познань нет возможности графика, оплата зарплаты минималка и после того как сдашь все документы с рейса начисляют остаток. Вычеты у парней знаю есть, у меня не было никогда, хоть даже ступеньку сломал с правой стороны в мерседесе. Высчитывают из-за того что я проанализировать смог, водитель мне рассказывает как он заполняет документы и я в шоке, люди топливо записывают общую, не разделяют РЭФ и основные быки, от того когда менеджер получает такой отчёт, он может делать с такими лохами что угод\r\nПриехал на работу , сказали ждать машину 5 дней.\r\n4 года отработал в Познаньской Гиртеке, на колоне TranseuPoland, ничего плохого сказать не могу, не знаю как у всех, меня нарушать просиди раза 3 , превысить 90 часов . Пошел навстречу. Вполне адекватная фирма, для начинающих вообще топ, документы делают все, за минимальную цену, на период обучения, оплачивают хостел, автобус возит на базу. Всегда , когда хотел выезжал на каженцию, я не привередлив, мне было пофиг, какая линия, машина, прицеп. Да есть эко балы, это минус, но у меня вроде получалось их делать без напряга. Вычет был один, единственный раз, 210 евро, долго ругался со сводным, но никак. По итогу его уволили, через месяца 4 , мутил что то там, возможно и с вычетами. Машины свежие\r\nГоворят шо гиртека закрывает польский парк, правда?\r\nЗа 1.5 года не доплатили 3 тыс евро отжал у них через суд трудовая инспекция вам в помощь','2026-05-12 09:21:20'),(2,'Интерком-НН','https://intercom-nn.ru/catalog/kompressory_dlya_kholodilnikov/N1112Y/','Нижний Новгород','Холодильные компрессоры','https://intercom-nn.ru/catalog/kompressory_dlya_kholodilnikov/N1112Y/','JIAXIPERA N1112Y (C00301996) компрессор для холодильника 140 Вт, R600, LBP',5101.00,3,3.40,5,0.600,0.500,0.380,55.83,'caution','Вы можете оценить качество работы нашего магазина и оставить отзыв о нашей работе. Обратите внимание, что отзывы могут оставлять только авторизованные пользователи. Прежде чем оставить отзыв, ознакомьтесь пожалуйста с правилами публикации отзывов на сайте\r\n\r\n10 марта 2024 Автор: Андрей Отзыв полезен? Да ( 0 ) Нет ( 0 ) Благодарю за качественную работу. Купленный товар (противовес для барабана стиральной машины) соответствует представленному в Вашем магазине.Товар качественный. С доставкой тоже не возникло никаких проблем.\r\n\r\nБлагодарю за качественную работу. Купленный товар (противовес для барабана стиральной машины) соответствует представленному в Вашем магазине.Товар качественный. С доставкой тоже не возникло никаких проблем.\r\n\r\n22 сентября 2023 Автор: Кульша Отзыв полезен? Да ( 0 ) Нет ( 0 ) не один раз уже оформлял заказы. Все четко, в течении одного дня оформление, оплата, отправка. Все приходит в срок через ТК, хорошо упаковано. Рекомендую.\r\n\r\nне один раз уже оформлял заказы. Все четко, в течении одного дня оформление, оплата, отправка. Все приходит в срок через ТК, хорошо упаковано. Рекомендую.','2026-05-12 11:00:19'),(3,'Интерком-НН','https://intercom-nn.ru/catalog/kompressory_dlya_kholodilnikov/069744103301/','Нижний Новгород','Холодильные компрессоры','https://intercom-nn.ru/catalog/kompressory_dlya_kholodilnikov/069744103301/','Атлант 69744103301 (69744107002, С-КО120Н5-02) Компрессор для холодильников Атлант, Стинол',33014475.00,2,3.40,5,0.600,0.500,0.380,55.83,'caution','Отзывы имеют смешанную тональность. Репутационный риск находится на среднем уровне. Интегральная оценка поставщика средняя, поэтому требуется осторожность. Надежность нового поставщика принята нейтральной, так как история фактических поставок отсутствует.','2026-05-12 11:19:38'),(4,'Интерком-НН','https://intercom-nn.ru/catalog/kompressory_dlya_kholodilnikov