CREATE TABLE `procurement_plan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `material_id` int NOT NULL,
  `quantity` int NOT NULL,
  `planned_date` date NOT NULL,
  `status` enum('planned','in_progress','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'planned',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_by` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_procurement_plan_material` (`material_id`),
  KEY `fk_procurement_plan_created_by` (`created_by`),
  CONSTRAINT `fk_procurement_plan_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_procurement_plan_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
