  `created_by` int NOT NULL,
  `status` enum('pending_logistician','pending_supplier','confirmed_supplier','approved','rejected','rejected_supplier','reschedule_requested') COLLATE utf8mb4_unicode_ci DEFAULT 'pending_logistician',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_requests_material` (`material_id`),
  KEY `fk_requests_supplier` (`supplier_id`),
  KEY `fk_requests_created_by` (`created_by`),
  CONSTRAINT `fk_requests_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_requests_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_requests_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
